text:
{
 "lead": {
  "es": "公立《こうりつ》の中学校《ちゅうがっこう》で、1つのクラスの人数《にんずう》の目安《めやす》（標準《ひょうじゅん》）を35人《にん》に下《さ》げる法律《ほうりつ》です。先生《せんせい》などの人数《にんずう》の目安《めやす》も変《か》えます。",
  "hs": "公立中学校の学級編制（1クラスの人数の決め方）の標準を35人に引き下げ、教職員定数（教職員の数）の標準を改める法律。"
 },
 "facts/0/text": {
  "es": "公立《こうりつ》の中学校《ちゅうがっこう》で、同《おな》じ学年《がくねん》の生徒《せいと》でつくる1クラスの人数《にんずう》の目安《めやす》を、40人《にん》から35人《にん》に下《さ》げます。令和《れいわ》10年《ねん》3月《がつ》31日《にち》までは、少《すこ》しずつ35人《にん》にしていきます。政令《せいれい》（内閣《ないかく》が決《き》めるきまり）で決《き》める学年《がくねん》などは40人《にん》です。",
  "hs": "公立中学校で、同じ学年の生徒で作る1学級の生徒数の標準を40人から35人に引き下げる。令和10年3月31日までは段階的に35人とし、政令で定める学年などは40人とする。"
 },
 "facts/1/text": {
  "es": "保健室《ほけんしつ》の先生《せんせい》（養護教諭《ようごきょうゆ》）などを、ひとつの学校《がっこう》に何人《なんにん》かおくための目安《めやす》を下《さ》げます。小学校《しょうがっこう》は851人《にん》以上《いじょう》から801人《にん》以上《いじょう》にします。中学校《ちゅうがっこう》は801人《にん》以上《いじょう》から751人《にん》以上《いじょう》にします。いくつかの学校《がっこう》の事務《じむ》をいっしょにする部屋《へや》（共同《きょうどう》学校《がっこう》事務室《じむしつ》）があります。この部屋《へや》を、いくつかの学校《がっこう》におく市町村《しちょうそん》の数《かず》に合《あ》わせて、事務《じむ》の職員《しょくいん》の数《かず》を計算《けいさん》します。",
  "hs": "養護教諭《ようごきょうゆ》（保健室の先生）などを複数配置する算定基準（数を決める目安）を、小学校は851人以上から801人以上、中学校は801人以上から751人以上に引き下げる。共同学校事務室（複数の学校の事務をまとめて行う組織）を複数の学校に置く市町村の数に応じて、事務職員の数を算定する。"
 },
 "facts/2/text": {
  "es": "この法律《ほうりつ》が使《つか》われ始《はじ》める日《ひ》（施行《しこう》）は、令和《れいわ》8年《ねん》4月《がつ》｜1日《ついたち》です。",
  "hs": "施行《しこう》（法律が効力をもつこと）は令和8年4月1日。"
 },
 "more/reason/text": {
  "es": "内閣《ないかく》は、つぎのためと説明《せつめい》しています。公立《こうりつ》の小学校《しょうがっこう》や中学校《ちゅうがっこう》などで、クラスの大《おお》きさと、先生《せんせい》などのおき方《かた》を、ちょうどよくするためです。そのために、公立《こうりつ》の中学校《ちゅうがっこう》などのクラスの人数《にんずう》の目安《めやす》と、公立《こうりつ》の小学校《しょうがっこう》や中学校《ちゅうがっこう》などの先生《せんせい》などの数《かず》の目安《めやす》を、変《か》える必要《ひつよう》があるとしています。※正《ただ》しくは「公立《こうりつ》の義務教育《ぎむきょういく》諸《しょ》学校《がっこう》」です。",
  "hs": "内閣は、公立の義務教育諸学校（小・中学校など）の学級規模と教職員の配置を適正にするため、公立中学校などの学級編制（クラスの人数）の標準と、公立の義務教育諸学校の教職員定数の標準を改める必要があるとしている。"
 },
 "more/who/text": {
  "es": "公立《こうりつ》の中学校《ちゅうがっこう》など（義務教育学校《ぎむきょういくがっこう》の後半《こうはん》と、中等教育学校《ちゅうとうきょういくがっこう》の前半《ぜんはん》をふくみます）の生徒《せいと》にかかわります。公立《こうりつ》の小学校《しょうがっこう》や中学校《ちゅうがっこう》などの保健室《ほけんしつ》の先生《せんせい》（養護教諭《ようごきょうゆ》）などや、事務《じむ》の職員《しょくいん》にもかかわります。共同《きょうどう》学校《がっこう》事務室《じむしつ》を、いくつかの学校《がっこう》におく市町村《しちょうそん》にもかかわります。※「後半《こうはん》」は正《ただ》しくは「後期《こうき》課程《かてい》」、「前半《ぜんはん》」は「前期課程《ぜんきかてい》」です。",
  "hs": "公立中学校など（義務教育学校の後期課程・中等教育学校の前期課程を含《ふく》む）の生徒、公立の義務教育諸学校（小・中学校など）の養護教諭《ようごきょうゆ》（保健室の先生）などや事務職員、共同学校事務室を複数の学校に置く市町村。"
 },
 "more/committee/text": {
  "es": "衆議院《しゅうぎいん》の文部科学委員会《もんぶかがくいいんかい》では、全員《ぜんいん》が賛成《さんせい》し、もとの案《あん》のまま通《とお》りました。参議院《さんぎいん》の文教科学委員会《ぶんきょうかがくいいんかい》では、35人《にん》学級《がっきゅう》の効果《こうか》や、先生《せんせい》を集《あつ》めるための取《と》り組《く》みについて質問《しつもん》がありました。先生《せんせい》などの数《かず》をふやす必要《ひつよう》などについても質問《しつもん》がありました。日本共産党《にほんきょうさんとう》が、案《あん》を直《なお》す修正案《しゅうせいあん》を出《だ》しました。事務《じむ》の職員《しょくいん》を、ひとつの学校《がっこう》に何人《なんにん》かおくための目安《めやす》を下《さ》げることなどが中身《なかみ》です。修正案《しゅうせいあん》は、みとめられませんでした（否決《ひけつ》）。法律案《ほうりつあん》は全員《ぜんいん》が賛成《さんせい》し、もとの案《あん》のまま通《とお》りました。どちらの委員会《いいんかい》でも、委員会《いいんかい》からの注文《ちゅうもん》（附帯決議《ふたいけつぎ》）がつけられました。",
  "hs": "衆議院の文部科学委員会は全会一致《ぜんかいいっち》で原案どおり可決した。参議院の文教科学委員会では、35人学級の効果、教員確保のための取り組み、教職員定数を増やす必要性などについて質疑があった。日本共産党が、事務職員を複数配置する算定基準の引き下げなどを内容とする修正案を出したが否決され、法律案は全会一致《ぜんかいいっち》で原案どおり可決された。両院の委員会で附帯決議《ふたいけつぎ》（委員会からの注文）がつけられた。"
 }
}
